#!/usr/bin/env bash
# Every colour comes from res/values/jetons.xml, generated by Synseria-Design: fails if that file was edited by
# hand, or if a colour is written anywhere else. A colour that is data, not design (a picture's, EDF's Tempo
# days), says so with "off-palette:" and its reason on its line or the line above.
[ -n "${BASH_VERSION:-}" ] || exec bash "$0" "$@"
set -euo pipefail
cd "$(dirname "$0")/../launcher/app/src/main"
tokens=res/values/jetons.xml
want=$(sed -n 3p "$tokens" | sed -E 's/.*contenu ([0-9a-f]+).*/\1/')
got=$(tail -n +4 "$tokens" | shasum -a 256 | cut -c1-16)
if [ "$want" != "$got" ]; then
  echo "$tokens was edited by hand: change Synseria-Design, then sh propager.sh Synema" >&2
  exit 1
fi
colour='#[0-9A-Fa-f]{3,8}\b|0x[0-9A-Fa-f]{8}\b|Color\.(parseColor|argb|rgb|WHITE|BLACK|RED|GREEN|BLUE|YELLOW|GRAY|DKGRAY|LTGRAY)\b'
found=$(grep -rnEI "$colour" java res --include='*.java' --include='*.xml' | grep -v "^$tokens:" | while IFS=: read -r file line rest; do
  prev=$([ "$line" -gt 1 ] && sed -n "$((line - 1))p" "$file" || true)
  # Masks that keep or set an alpha are not colours, nor are XML's numeric entities (&#160;).
  bare=$(sed -E 's/0x00FFFFFF|0x[0-9A-Fa-f]{2}000000|&#[0-9]+;//g' <<<"$rest")
  grep -qE "$colour" <<<"$bare" || continue
  [[ "$rest$prev" == *off-palette:* ]] || echo "$file:$line:$rest"
done)
if [ -n "$found" ]; then
  echo "colours outside jetons.xml (use @color/syn_*, or mark data colours off-palette: <why>):" >&2
  echo "$found" >&2
  exit 1
fi
